func (o *WorkflowVersion) Workflow(mods ...bob.Mod[*dialect.SelectQuery]) WorkflowsQuery {
	return Workflows.Query(append(mods,
		sm.Where(Workflows.Columns.ID.EQ(psql.Arg(o.WorkflowID))),
	)...)
}

func (os WorkflowVersionSlice) Workflow(mods ...bob.Mod[*dialect.SelectQuery]) WorkflowsQuery {
	pkWorkflowID := make(pgtypes.Array[string], 0, len(os))

	// the array is only a filter (semi-join), so duplicate keys can be
	// dropped before they are sent over the wire
	seenWorkflowID := make(map[string]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenWorkflowID[o.WorkflowID]; ok {
			continue
		}
		seenWorkflowID[o.WorkflowID] = struct{}{}
		pkWorkflowID = append(pkWorkflowID, o.WorkflowID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkWorkflowID), "text[]"))

	return Workflows.Query(append(mods,
		sm.Where(Workflows.Columns.ID.EQ(PKArgExpr)),
	)...)
}

