// HasWorkflow filters parents that have a matching Workflow using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Workflows).
func (w workflowVersionWhereR[Q]) HasWorkflow(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Workflows.NameExpr()),
		sm.Where(Workflows.Columns.ID.EQ(w.cols.WorkflowID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}
